func (r *GormMeetingRfpRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*meeting_rfpv1.MeetingRfp, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*meeting_rfpv1.MeetingRfp, string, error) {
		return r.List(ctx, in)
	})
}

