// DeleteMeetingRfp queues a soft delete. A record already deleted or gone is
// not an error: two batches deleting the same record must not fail each other.
func (b *gormBatch) DeleteMeetingRfp(name string) {
	r := &GormMeetingRfpRepository{DB: b.db, Retention: b.retention}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueMeetingRfpDelete(b.u, name, false)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.markDeleted(ctx, tx, key).Error
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/MeetingRfp", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getMeetingRfp)})
}

// PurgeMeetingRfp queues the record's removal for good. A record already
// gone is not an error: two batches clearing the same row must not fail each
// other.
func (b *gormBatch) PurgeMeetingRfp(name string) {
	// A record something still refers to is kept, as Purge keeps it.
	r := &GormMeetingRfpRepository{DB: b.db, Refs: b.u.Conn().References}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	keep := queueMeetingRfpPurge(b.u, name)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		if *keep {
			return nil
		}
		if _, err := r.purge(ctx, tx, key, name, false); err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			return err
		}
		return nil
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/MeetingRfp", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getMeetingRfp)})
}
